import type {
	FormatDiagnostic,
	FormatInput,
	FormatPlugin,
	FormatResult,
	InputPolygons,
	PlacementOutput,
	SourcePolygon,
	SvgDocuments
} from '@svgnest/format-plugin';

export interface SvgFormatConfig {
	curveTolerance: number;
}

/** The input-facing exports generated by wasm-bindgen from svg-format-algo. */
export interface SvgFormatWasm {
	input_to_svg(input: Uint8Array): string;
	input_to_polygons(input: Uint8Array, tolerance: number): string;
}

export interface SvgOutputWasm extends SvgFormatWasm {
	output_to_svg(input: Uint8Array, placementJson: string): string;
}

type PolygonPayload = {
	polygons: Array<{ source: number; points: number[] }>;
	sources: number[];
};

/**
 * DOM-free base adapter for Rust input conversion. SvgFormatPlugin extends it
 * with the Rust placement-output methods.
 */
export class SvgInputAdapter {
	readonly id = 'svg';
	readonly extensions = ['.svg'] as const;

	constructor(protected readonly wasm: SvgFormatWasm) {}

	async inputToSvg(input: FormatInput, _config: SvgFormatConfig): Promise<FormatResult<string>> {
		return { value: this.wasm.input_to_svg(toUtf8(input)), diagnostics: [] };
	}

	async inputToPolygons(input: FormatInput, config: SvgFormatConfig): Promise<FormatResult<InputPolygons>> {
		const payload = decodePolygons(this.wasm.input_to_polygons(toUtf8(input), config.curveTolerance));
		return {
			value: {
				polygons: payload.polygons.map(({ source, points }) => withSource(points, source)),
				sources: payload.sources
			},
			diagnostics: []
		};
	}
}

/**
 * Complete SVG implementation of the format-plugin contract. Both output
 * methods deliberately delegate to the same Rust renderer while SVG is the
 * only persisted output format.
 */
export class SvgFormatPlugin extends SvgInputAdapter implements FormatPlugin<FormatInput, SvgFormatConfig, SvgDocuments> {
	declare protected readonly wasm: SvgOutputWasm;

	constructor(wasm: SvgOutputWasm) {
		super(wasm);
	}

	async outputToSvg(input: FormatInput, placing: PlacementOutput): Promise<FormatResult<SvgDocuments>> {
		return { value: decodeDocuments(this.wasm.output_to_svg(toUtf8(input), JSON.stringify(placing))), diagnostics: [] };
	}

	async outputToData(input: FormatInput, placing: PlacementOutput): Promise<FormatResult<SvgDocuments>> {
		return this.outputToSvg(input, placing);
	}
}

function toUtf8(input: FormatInput): Uint8Array {
	return typeof input === 'string' ? new TextEncoder().encode(input) : input;
}

function withSource(points: number[], source: number): SourcePolygon {
	if (!Number.isSafeInteger(source) || source < 0) throw new Error('Rust SVG core returned an invalid source index');
	if (points.length % 2 || points.some(point => !Number.isFinite(point))) {
		throw new Error('Rust SVG core returned invalid polygon coordinates');
	}
	const polygon = [...points] as SourcePolygon;
	polygon.source = source;
	return polygon;
}

export function decodePolygons(payload: string): PolygonPayload {
	let value: unknown;
	try {
		value = JSON.parse(payload);
	} catch {
		throw new Error('Rust SVG core returned malformed polygon JSON');
	}
	if (!value || typeof value !== 'object') throw new Error('Rust SVG core returned an invalid polygon payload');
	const { polygons, sources } = value as Partial<PolygonPayload>;
	if (!Array.isArray(polygons) || !Array.isArray(sources)) {
		throw new Error('Rust SVG core returned an invalid polygon payload');
	}
	return { polygons, sources };
}

function decodeDocuments(payload: string): SvgDocuments {
	let value: unknown;
	try {
		value = JSON.parse(payload);
	} catch {
		throw new Error('Rust SVG core returned malformed output JSON');
	}
	if (!value || typeof value !== 'object' || !Array.isArray((value as Partial<SvgDocuments>).documents)) {
		throw new Error('Rust SVG core returned an invalid output payload');
	}
	const documents = (value as SvgDocuments).documents;
	if (documents.some(document => typeof document !== 'string')) {
		throw new Error('Rust SVG core returned an invalid SVG document');
	}
	return { documents };
}

export { loadSvgFormatPlugin } from './wasm-loader.ts';
export type { FormatDiagnostic };
